import Foundation

/// Only checks advertised pasteboard type identifiers, never item contents.
/// Some pasteboard owners attach a concealed/transient marker to a non-first
/// item, so callers must examine all items rather than only the first type list.
public enum ClipboardSensitiveTypePolicy {
    private static let prohibitedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType"
    ]

    public static func shouldSkip(typeNamesByItem: [[String]]) -> Bool {
        typeNamesByItem.contains { item in
            item.contains { prohibitedTypes.contains($0) }
        }
    }
}
